import type { NextRequest } from "next/server";
import { completeEmailSignIn } from "@/lib/server/auth-callback";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * One-time sign-in hand-off. Either path works:
 *   ?code=...              PKCE code from a magic-link email
 *   ?token_hash=...&type=  token generated by /api/admin/login
 *
 * The session is written to HttpOnly cookies on this response, so the browser
 * never holds the token after the redirect.
 */
export async function GET(request: NextRequest) {
  const url = new URL(request.url);
  const { response } = await completeEmailSignIn(request, {
    code: url.searchParams.get("code"),
    tokenHash: url.searchParams.get("token_hash"),
    type: url.searchParams.get("type"),
  });
  return response;
}
